parameters.jsCode:
/* 
  🛡️ N8N OUTPUT GUARDRAILS - V8.1 (Content Unwrap Fix)
  - Suporta retornos de ferramentas dinâmicas
  - Bloqueia vazamentos de tool-calls e prompts
  - Formata dados técnicos (links, boletos) de forma amigável
  - FIX V8.1: Extrai corretamente o campo 'content' do wrapper JSON do LLM
*/

const rawResponse = $('Edit Fields Normaliza Conversation FINAL').first().json.ai_response || "";
let msg = String(rawResponse).trim();

/**
 * Tenta extrair a mensagem amigável de dentro de objetos complexos
 * retornados pelas ferramentas ou pelo LLM.
 */
function parseAiResponse(obj) {
    if (typeof obj === 'string') {
        if (obj.startsWith('{') || obj.startsWith('[')) {
            try {
                const inner = JSON.parse(obj);
                return parseAiResponse(inner);
            } catch (e) { return obj; }
        }
        return obj;
    }

    if (!obj || typeof obj !== 'object') return "";

    let mainText = obj.content || obj.message || obj.text || obj.response?.message || obj.out || "";
    let extras = [];

    const seekData = (target) => {
        if (!target || typeof target !== 'object') return;

        if (target.link) extras.push(`\n\n🔗 *Link:* ${target.link}`);
        if (target.url) extras.push(`\n\n🌐 *Acesse:* ${target.url}`);
        if (target.codigo_barras || target.linha_digitavel) {
            const code = target.codigo_barras || target.linha_digitavel;
            extras.push(`\n\n📑 *Linha Digitável:*\n\`${code}\``);
        }
        if (target.vencimento || target.data_vencimento) {
            const date = target.vencimento || target.data_vencimento;
            extras.push(`\n📅 *Vencimento:* ${date}`);
        }
        if (target.status_pagamento) extras.push(`\n✅ *Status:* ${target.status_pagamento}`);

        Object.values(target).forEach(v => seekData(v));
    };

    seekData(obj);

    const uniqueExtras = [...new Set(extras)];
    const finalResult = (mainText + uniqueExtras.join("")).trim();

    return finalResult || (Object.keys(obj).length > 0 ? JSON.stringify(obj) : "");
}

// 1. Processamento Inicial
msg = parseAiResponse(rawResponse);

// === FAILSAFE V8.1 — Extração dupla para encoding não-padrão do N8N ===
// O JSON.parse interno pode falhar com strings multiline escapadas.
// Esta camada extra garante extração mesmo nesses casos.
if (typeof msg === 'string' && msg.trimStart().startsWith('{')) {
    try {
        const parsed = JSON.parse(msg);
        if (parsed && parsed.content) {
            msg = parsed.content;
        }
    } catch(e) {
        // Fallback por regex — mais tolerante a variações de encoding
        const match = msg.match(/"content"\s*:\s*"([\s\S]+?)(?="\s*\n?\s*\})/);
        if (match) {
            msg = match[1]
                .replace(/\\n/g, '\n')
                .replace(/\\"/g, '"')
                .replace(/\\\\/g, '\\');
        }
    }
}
// === FIM DO FAILSAFE ===

// 2. Regras de Bloqueio (Guardrails)
let blocked = false;
const sqlPatterns = /(select|insert|update|delete|drop|truncate|alter|create|union|exec|information_schema)\s/i;

if (msg.length < 2) {
    blocked = true;
    msg = "Puxa, não consegui processar essa informação agora. Poderia repetir?";

} else if (/prompt de sistema|minhas instruções|ignore as instruções|instruções base|diretrizes de governança/i.test(msg)) {
    blocked = true;
    msg = "Desculpe, sou um assistente virtual e não estou autorizado a compartilhar detalhes técnicos da minha configuração.";

} else if (sqlPatterns.test(msg) && !msg.includes("http")) { 
    blocked = true;
    msg = "Identificamos um formato de resposta inadequado. Como posso te ajudar de outra forma?";

} else if (/^Calling .+Tool with input:/i.test(msg) || /"tool_name":/i.test(msg) || /"parameters":/i.test(msg)) {
    blocked = true;
    msg = "Estou processando sua solicitação... Um momento, por favor.";
}

// 3. Limpeza Final
msg = msg.replace(/<thought>[\s\S]*?<\/thought>/gi, '').trim();
msg = msg.replace(/```json/gi, '').replace(/```/gi, '').trim();

return [{
  json: {
    is_blocked: blocked,
    message: msg,
    original_ai_payload: rawResponse
  }
}];

