parameters.description:
={{
(() => {
  const agent = $('RPC - Acesso Entrada').first()?.json?.context?.agent;

  if (!agent) return 'Erro: agent não encontrado';

  const tools = (agent.sub_agents || [])
    .filter(sa => sa?.is_gatekeeper === true)
    .flatMap(sa => sa?.tools || []);

  if (!tools.length) {
    return 'Nenhuma ferramenta de validação disponível.';
  }

  const lista = tools.map(t => {
    const name = t?.name || 'unknown_tool';
    const description = t?.description || 'Sem descrição disponível';

    // ===== BASE =====
    let required = t?.parameters?.required || [];
    const properties = t?.parameters?.properties || {};
    const bodyMapping = t?.body_mapping || {};

    const hasParams = Object.keys(properties).length > 0;
    const hasBody = Object.keys(bodyMapping).length > 0;

    // 🔥 Detecta parâmetro interno (<...>)
    const isInternal = (value) =>
      typeof value === 'string' &&
      value.startsWith('<') &&
      value.endsWith('>');

    // 🔥 Se não tem required mas tem body → vira obrigatório
    if ((!required || required.length === 0) && hasBody) {
      required = Object.keys(bodyMapping);
    }

    // ===== CLASSIFICAÇÃO =====
    const userParams = [];
    const internalParams = [];

    required.forEach(param => {
      const mappingValue = bodyMapping[param];

      if (mappingValue && isInternal(mappingValue)) {
        internalParams.push(param);
      } else {
        userParams.push(param);
      }
    });

    // ===== DESCRIÇÃO USER =====
    let userDesc = '';

    if (userParams.length > 0) {
      userDesc = userParams
        .map(p => {
          const desc = properties[p]?.description || 'informação necessária';
          return `- ${p} (obrigatório): ${desc}`;
        })
        .join('\n');
    } else {
      userDesc = 'nenhum dado adicional do usuário necessário';
    }

    // ===== DESCRIÇÃO INTERNA =====
    let internalDesc = '';

    if (internalParams.length > 0) {
      internalDesc = `
dados internos (já disponíveis no sistema — NÃO solicitar ao usuário):
${internalParams.map(p => `- ${p}`).join('\n')}
`;
    }

    // ===== PAYLOAD =====
    const bodyDesc = hasBody
      ? Object.entries(bodyMapping)
          .map(([k, v]) => `- ${k} ← ${v}`)
          .join('\n')
      : null;

    return `🔐 tool_name: "${name}"
descrição: ${description}

dados que você deve obter do usuário:
${userDesc}${internalDesc}

${bodyDesc ? `payload enviado automaticamente pelo sistema:\n${bodyDesc}` : ''}
`;
  }).join('\n');

  return `Você é o Proxy Universal de Validação.

Sua função é validar a identidade do usuário antes de permitir acesso a qualquer informação protegida.

=== FERRAMENTAS DE VALIDAÇÃO DISPONÍVEIS ===
${lista}

=== REGRAS DE EXECUÇÃO ===
1. Sempre utilize uma das ferramentas acima para validar a identidade.
2. Use exatamente o valor de "tool_name" listado.
3. Solicite ao usuário apenas os dados explicitamente indicados como necessários.
4. Nunca solicite dados internos do sistema (como IDs ou identificadores técnicos).
5. Se já possuir os dados necessários, execute a ferramenta imediatamente.
6. Nunca invente ou assuma dados.
7. Não execute nenhuma ação de negócio — apenas validação.`;
})()
}}

