parameters.jsCode:
/* 
  🛡️ N8N OUTPUT GUARDRAILS - V10.2 (Recursive Deep Clean)
*/

// 1. Captura segura
const rpcData = $('Roteador de Contexto').first()?.json || {};
const rawPayload = $('Edit Fields Normaliza Conversation FINAL1').first();
const rawResponse = rawPayload?.json?.ai_response || "";
let originalRaw = String(rawResponse);

// 2. FUNÇÃO DE LIMPEZA PROFUNDA (Recursiva)
function deepCleanMessage(text) {
    if (!text) return "";

    let current = text.trim();

    // Remove blocos de código Markdown
    current = current.replace(/```json/gi, '').replace(/```/gi, '').trim();

    try {
        // Tenta parsear. Se for objeto, tenta pegar o campo de conteúdo e repetir.
        const parsed = JSON.parse(current);
        if (typeof parsed === 'object' && parsed !== null) {
            const inner = parsed.content || parsed.message || parsed.output || parsed.text || JSON.stringify(parsed);
            return deepCleanMessage(inner); // Recursão para limpar o JSON de dentro
        }
    } catch (e) {
        // Não é JSON válido, segue para limpeza de string
    }

    // Limpeza de Regex para quando o JSON está quebrado ou parcial
    // Procura o valor após "content": ou "message":
    const contentRegex = /"(?:content|message|output|text)":\s*"([\s\S]*?)"(?:\s*[,}])?$/i;
    const match = current.match(contentRegex);
    if (match && match[1]) {
        return deepCleanMessage(match[1]);
    }

    return current;
}

let msg = deepCleanMessage(originalRaw);

// 3. EXTRAÇÃO DE TRANSIÇÃO E LIMPEZA FINAL
const transitionMatch = msg.match(/\[TRANSITION_TO[:\s]+(\w+)\]/i);
const transitionTarget = transitionMatch ? transitionMatch[1].trim() : null;

msg = msg
    .replace(/\[TRANSITION_TO[:\s]+\w+\]/gi, '') // Remove a tag de transição
    .replace(/\\n/g, '\n')                       // Converte quebras de linha escapadas
    .replace(/\\"/g, '"')                        // Converte aspas escapadas
    .replace(/^["' :{}]+|["' {}]+$/g, '')        // Remove lixo de JSON nas bordas (pontos e chaves)
    .trim();

// 4. FILTROS DE SEGURANÇA
let blocked = false;
if (msg.length < 2) {
    blocked = true;
    msg = "Puxa, não consegui processar essa informação agora. Poderia repetir?";
} else if (/prompt de sistema|minhas instruções|ignore as instruções/i.test(msg)) {
    blocked = true;
    msg = "Desculpe, sou um assistente virtual e não estou autorizado a compartilhar detalhes técnicos.";
}

return [{
    is_blocked: blocked,
    message: msg,
    transition_target: transitionTarget,
    p_current_step: transitionTarget || rpcData.currentStep,
    original_ai_payload: originalRaw
}];

