parameters.jsCode:
/* 🛡️ FORMATACAO V12.0 - Link Recovery System */
const rpcData = $node["Roteador de Contexto"].json;
const aiNode = $node["Edit Fields Normaliza Conversation FINAL1"].json;

let raw = aiNode.ai_response || aiNode.output || aiNode.content || "";
let msg = String(raw).trim();

// 1. Extração Inteligente (Recupera pedaços se a IA quebrar o JSON)
function extractCleanContent(text) {
    // Tenta capturar TODOS os valores de "content" no texto
    const regex = /"content":\s*"([\s\S]*?)"/gi;
    let matches = [];
    let match;

    while ((match = regex.exec(text)) !== null) {
        matches.push(match[1]);
    }

    if (matches.length > 0) {
        // Une todos os pedaços encontrados (caso a IA tenha quebrado o link)
        return matches.join("").replace(/\\n/g, '\n').replace(/\\"/g, '"');
    }

    // Fallback para JSON.parse se o regex falhar
    try {
        const parsed = JSON.parse(text);
        return parsed.content || parsed.output || text;
    } catch (e) {
        return text;
    }
}

msg = extractCleanContent(msg);

// 2. Captura da Transição
const transitionMatch = raw.match(/\[TRANSITION_TO[:\s]+(\w+)\]/i);
const nextStep = transitionMatch ? transitionMatch[1].trim() : rpcData.currentStep;

// 3. LIMPEZA PROFUNDA
let cleanMsg = msg;
cleanMsg = cleanMsg.replace(/Comando:[\s\S]*?(?=<output>|$)/gi, ''); 
cleanMsg = cleanMsg.replace(/Transições:[\s\S]*?$/gi, '');
cleanMsg = cleanMsg.replace(/\[TRANSITION_TO[:\s]+\w+\]/gi, '');
cleanMsg = cleanMsg.replace(/<[^>]*>?/gm, '');

// Limpeza de aspas e chaves remanescentes
cleanMsg = cleanMsg.replace(/^["':{} \n]+|["':{} \n]+$/g, '');

return [{
  json: {
    p_conversation_id: rpcData.p_conversation_id,
    p_current_step: nextStep,
    message: cleanMsg.trim(),
    has_transition: !!transitionMatch
  }
}];

